import { firaCodeBoldUrl, firaCodeRegularUrl } from "./fonts-data";

// Fonts inlined as base64 data URIs (src/fonts-data.ts, generated by
// scripts/inline-fonts.cjs): no fetch, no network dependency at render time.
export const fontFamily = "Fira Code";

// Load via the FontFace API directly instead of @remotion/fonts loadFont():
// loadFont holds a delayRender handle until the font resolves. When
// Remotion's frame-retry path reloads the page mid-render (e.g. after a
// compositor "Request closed"), the fresh page's font.load() sometimes
// never settles, the handle hits the delayRender timeout, and the render
// dies with the font error masking the real one. Fire-and-forget here; the
// blocking gate lives in calculateMetadata via waitUntilDone() below, and
// that wait is bounded.
const loadOne = (url: string, weight: string) =>
  new FontFace(fontFamily, `url('${url}') format('truetype')`, {
    weight,
  })
    .load()
    .then((face) => {
      document.fonts.add(face);
    });

// FontFace only exists in the browser; under Node (vitest) there is no
// DOM to load fonts into, so resolve immediately.
let settled = typeof FontFace === "undefined";
const fontReady =
  typeof FontFace === "undefined"
    ? Promise.resolve()
    : Promise.all([
        loadOne(firaCodeRegularUrl, "400"),
        loadOne(firaCodeBoldUrl, "700"),
      ]).then(() => {
        settled = true;
      });

/**
 * Bounded wait for the fonts, called from calculateMetadata. Normally the
 * fonts are ready in milliseconds; if loading ever wedges (see above), we
 * proceed after 15s with a loud warning - code clips render in a fallback
 * monospace for that tab instead of killing the whole render.
 */
export const waitUntilDone = () =>
  Promise.race([
    fontReady,
    new Promise<void>((resolve) => setTimeout(resolve, 15000)),
  ]).then(() => {
    if (!settled) {
      console.warn(
        `[font] ${fontFamily} did not finish loading within 15s; ` +
          `continuing with fallback font`,
      );
    }
  });

export const fontSize = 40;
export const tabSize = 3;
export const horizontalPadding = 60;
export const verticalPadding = 84;
